// Uso: node check-migration.mjs <archivo.sql>
import { readFileSync } from 'node:fs';

const file = process.argv[2];
const sql = readFileSync(file, 'utf8');
const rules = [
  [/\bDROP\s+(TABLE|COLUMN)\b/i, 'Borra datos: requiere aprobación humana.'],
  [/\bALTER\s+COLUMN\b.*\bTYPE\b/i, 'Cambiar un tipo puede bloquear la tabla.'],
  [/\bADD\s+COLUMN\b(?![^;]*\bDEFAULT\b)[^;]*\bNOT\s+NULL\b/i, 'NOT NULL sin DEFAULT falla si la tabla tiene filas.'],
];
const problems = rules.filter(([rule]) => rule.test(sql)).map(([, message]) => message);

if (problems.length) {
  problems.forEach((p) => console.error(`${file}: ${p}`));
  process.exit(1);
}
console.log(`${file}: sin problemas detectados`);

